@spec vm_snap_temper_spec  src=tests/specs/vm_snap_temper_spec.lua  loc=107  cases=5
@exercises tuning (tuning), trackerView (h.vm), editCursor (h.ec)
@surface   tuning.derive, vm:setGridSize, tuning.stepToMidi, vm:snapToTemper, ec:setSelection
@harness   mk{seed.notes}

# Intent
  Notation snap: tv:snapToTemper(scope) runs every note in scope
  through tuning.snap and writes the pair back. The temper is a twelve-note
  quarter-comma meantone MOS, so a step's seat carries a detune of its own
  and the window is asymmetric (+38.0 / -58.6 either side of step 1).

# Helpers
  @fn mk(harness, notes)  @ 16-23
  @fn note(ppq, pitch, detune)  @ 25-28
  @fn lane1(h)  @ 30-34
  @fn cell(h, row)  @ 36
  @fn near(a, b, msg)  @ 38-40
  @fn seat(step, oct)  @ 43
      -- Seat of (step, octave) under MEAN, as the spec's expectation frame.

# Cases
  @case 'snapToTemper(all) seats an off-step note on its own step'  [harness]  @ 47-56
  @case 'a note past the half-way point lands on its neighbour'  [harness]  @ 60-69
  @case 'a note inside the window keeps its step'  [harness]  @ 73-80
  @case 'a note already on its step is left where it is'  [harness]  @ 84-92
  @case 'a selection confines the snap to the notes inside it'  [harness]  @ 96-105

# Uses (outbound edges)
  @use call tuning.derive  @ 9
  @use call vm:setGridSize  @ 21
  @use call tuning.stepToMidi  @ 43
  @use call vm:snapToTemper  @ 50,64,76,88,101
  @use call ec:setSelection  @ 99

